put(root,original.toUtf8());put(child,childText.toUtf8());put(bib,bibText.toUtf8());put(cls,"\\ProvidesClass{school}\n\\LoadClass{article}\n");
auto *w=new TeXDocumentWindow(root);w->resize(1000,760);w->show();check("article ready",waitFor([&]{return w->property("researchArticleReady").toBool()&&w->property("researchArticleMode").toBool();}));
Recording recording;const bool record=qEnvironmentVariableIsSet("TEXLINE_INTUITIVE_RECORD");if(record){for(int pass=0;pass<2;++pass){w->typeset();check("recording sample compile "+QString::number(pass),waitFor([&]{return !w->isTypesetting()&&!w->property("researchBuildPreparing").toBool()&&!w->property("researchBuildFinishing").toBool()&&!w->property("researchPublishing").toBool();},45000));}check("recording sample has a certified PDF",!Research::previewFile(root).isEmpty()&&Research::pdfPairValid(Research::previewFile(root)));recording.start(folder+"/recording",w);}
auto cursor=w->textCursor();cursor.setPosition(original.indexOf("Writing"));cursor.setPosition(cursor.position()+7,QTextCursor::KeepAnchor);w->editor()->setTextCursor(cursor);w->editor()->ensureCursorVisible();const int position=cursor.position(),anchor=cursor.anchor();
auto *outline=w->findChild<QAction*>("researchOutlineAction");if(!outline->isChecked())outline->trigger();auto *objects=w->findChild<QToolButton*>("researchArticleObjects");objects->setChecked(true);auto *tree=w->findChild<QTreeWidget*>("researchArticleTree");QTreeWidgetItem *object=nullptr;{QTreeWidgetItemIterator it(tree);while(*it){if((*it)->data(0,Qt::UserRole+1).toInt()==1){object=*it;break;}++it;}}
check("included equation appears in its section",object&&object->parent()&&object->parent()->text(0)=="Proof and evidence");if(object){if(object->parent())object->parent()->setExpanded(true);tree->scrollToItem(object);settle(250);check("the lookup row is visible before activation",tree->viewport()->rect().intersects(tree->visualItemRect(object)));if(record)recording.clickAt(tree->viewport(),tree->visualItemRect(object).center());else tree->itemClicked(object,0);}
auto *pin=w->findChild<QDockWidget*>("researchPinnedReference");check("one click reads included equation alongside writing",pin&&waitFor([&]{return pin->property("researchPinnedReady").toBool();}));if(record)check("compiled included equation uses the existing PDF excerpt",pin&&pin->property("researchPinnedVisual").toBool());check("reading object retains writing selection",w->cursorPosition()==position&&w->textCursor().anchor()==anchor&&w->textDoc()->editorText()==original);if(pin)check("reference preview points to the included source",QFileInfo(referenceReadingState(w).value("pinFile").toString())==QFileInfo(child)&&referenceReadingState(w).value("pinKey").toString()=="eq:evidence");settle(250);w->grab().save(folder+"/article-read-alongside.png");if(record){recording.action("Read the included equation without leaving the writing selection");settle(900);}if(pin)w->findChild<QToolButton*>("researchPinnedClose")->click();
cursor=w->textCursor();cursor.setPosition(original.indexOf("\\cite")+8);w->editor()->setTextCursor(cursor);w->findChild<QAction*>("researchInsertCitation")->trigger();auto *cite=w->findChild<QDialog*>("researchCitationDialog");check("existing citation reopens selector",cite);check("citation dialog reuses the existing navigation shortcuts",cite&&cite->actions().contains(w->findChild<QAction*>("researchNavigateBack"))&&cite->actions().contains(w->findChild<QAction*>("researchNavigateForward")));if(cite){auto *list=cite->findChild<QListWidget*>("researchCitationList");check("local bibliography is loaded",waitFor([&]{return list->count()==1;}));auto *locator=cite->findChild<QLineEdit*>("researchCitationLocator");locator->setText("12--14");auto *search=cite->findChild<QLineEdit*>("researchCitationSearch");search->setText("evidence");check("link bibliography stays discoverable",cite->findChild<QToolButton*>("researchCitationAdd")->isVisible()&&cite->findChild<QToolButton*>("researchCitationAdd")->menu()->actions().size()>=5);cite->findChild<QAction*>("researchCitationOpenSource")->trigger();settle(180);auto *bibliography=TeXDocumentWindow::findDocument(bib);check("edit entry opens the actual selected record",bibliography&&!cite->isVisible()&&bibliography->textCursor().selectedText().contains("custom={preserve me}"));if(bibliography){check("bibliography editor keeps the manuscript root",QFileInfo(bibliography->textDoc()->getRootFilePath())==QFileInfo(root));if(record){recording.follow(bibliography);recording.action("Edit the original bibliography record");settle(700);}auto edit=bibliography->textCursor();const int at=bibliography->textDoc()->editorText().indexOf("Original evidence");edit.setPosition(at);edit.setPosition(at+17,QTextCursor::KeepAnchor);edit.insertText("Revised evidence");bibliography->editor()->undo();check("bibliography edit undo restores exact comments and fields",bibliography->textDoc()->editorText()==bibText);bibliography->editor()->redo();bibliography->findChild<QAction*>("researchNavigateBack")->trigger();check("Back restores the same citation selector",waitFor([&]{return cite->isVisible()&&cite->findChild<QLabel*>("researchCitationTitle")->text()=="Revised evidence";}));check("return keeps query and locator",search->text()=="evidence"&&locator->text()=="12--14");w->findChild<QAction*>("researchNavigateForward")->trigger();settle();check("Forward returns to the bibliography editor",!cite->isVisible()&&bibliography->editor()->hasFocus());auto again=bibliography->textCursor();const auto nextAt=bibliography->textDoc()->editorText().indexOf("Revised evidence");again.setPosition(nextAt);again.setPosition(nextAt+16,QTextCursor::KeepAnchor);again.insertText("Further evidence");bibliography->findChild<QAction*>("researchNavigateBack")->trigger();check("repeated Back reloads later bibliography edits",waitFor([&]{return cite->isVisible()&&cite->findChild<QLabel*>("researchCitationTitle")->text()=="Further evidence";}));cite->grab().save(folder+"/citation-return.png");if(record){recording.follow(w);recording.action("Back restores the citation query and page range");settle(1000);}}cite->reject();settle();}
check("editing bibliography leaves manuscript unchanged",w->textDoc()->editorText()==original&&bytes(root)==original.toUtf8()&&bytes(bib)==bibText.toUtf8());
